    def collect_uplane_l1_iq_data(self, target_output_file_path, module_dn, sfn, slot, capture_mode, timeout=120):
        """
        Collect UplaneL1IQData

        :param str target_output_file_path: path to output file
        :param str module_dn: Runtime DN of BBMOD or SMOD DN that not support pluggable BBMOD
        :param int sfn: [0-65535]
        :param int slot: [0-79]
        :param str capture_mode: one of (ScheduleSynchronousStopOfOngoingContinuousCapture', 'StartNewScheduledCapture')
        :param int timeout: (optional) Timeout for the operation, defaults to 120
        """

        params_to_check = {'sfn': sfn, 'slot': slot, 'capture_mode': capture_mode}

        self._validation_uplance_l1_iq_data_params(params_to_check)

        parameters = {"moduleDN": module_dn,
                      "sfn": sfn,
                      "slot": slot,
                      "captureMode": capture_mode}

        return self._api_client.execute_procedure(name="collectUPlaneL1IQData",
                                                  parameters=parameters,
                                                  timeout=timeout,
                                                  output_file_name=target_output_file_path)

    def _validation_uplance_l1_iq_data_params(self, params):

        sfn = (0 <= params['sfn'] <= 65535)
        slot = (0 <= params['slot'] <= 79)
        capture_mode = (params['capture_mode'] in ("ScheduleSynchronousStopOfOngoingContinuousCapture",
                                                   "StartNewScheduledCapture"))

        params_to_check = {'sfn': sfn, 'slot': slot, 'capture_mode': capture_mode}

        self._check_params(params_to_check, params, "tutorial-collectUPlaneL1IQData.html")

    def _check_params(self, params_to_check, params, subpage):
        for param in params_to_check:
            if params_to_check[param] is False:
                raise_value_error(param=param,
                                  value=str(params[param]),
                                  subpage=subpage)

    def configure_uplane_l1_iq_data(self, module_dn, capture_on_event, dl_nr_subcell_list=None, ul_nr_subcell_list=None,
                                    dl_lte_subcell_list=None, ul_lte_subcell_list=None, timeout=120):

        """
        Configure UPlaneL1IQData

        :param str module_dn: Runtime DN of BBMOD or SMOD DN that support embeded BBMOD
        :param bool capture_on_event: True or False
        :param list[int] dl_nr_subcell_list: [<0-7>], (optional, but one of dlNrSubcellList|ulNrSubcellList|
                                                      dlLteCellList|ulLteCellList must be configured, maxItems is 2),
        :param list[int] ul_nr_subcell_list:[<0-7>], (optional, but one of dlNrSubcellList|ulNrSubcellList|
                                                      dlLteCellList|ulLteCellList must be configured, maxItems is 2),
        :param list[int] dl_lte_subcell_list: [<0-65535>], (optional, but one of dlNrSubcellList|ulNrSubcellList|
                                                            dlLteCellList|ulLteCellList must be configured,maxItems is2)
        :param list[int] ul_lte_subcell_list:[<0-65535>], (optional, but one of dlNrSubcellList|ulNrSubcellList|
                                                            dlLteCellList|ulLteCellList must be configured,maxItems is2)
        :param Union[int,str] timeout: (optional) Timeout for the operation, defaults to 120
        :param int timeout: (optional) Timeout for the operation, defaults to 120
        :raises DataNotAvailable: If Configure UPlaneL1IQData status has not been provided by M-Plane.
        :raises KeyError: If none of dlNrSubcellList|ulNrSubcellList|dlLteCellList|ulLteCellList is provided
        :raises ValueError: If none of dlNrSubcellList|ulNrSubcellList|dlLteCellList|ulLteCellList is list object
        :return: str: status of the operation

        More details:
        https://onion.wroclaw.nsn-rdnet.net/branches/master/cli-docs/tutorial-configureUPlaneL1IQData.html
        """

        params = [dl_nr_subcell_list, ul_nr_subcell_list, dl_lte_subcell_list, ul_lte_subcell_list]

        if not any(params):
            msg = "One of dl_nr_subcell_list | ul_nr_subcell_list | dl_lte_subcell_list | ul_lte_subcell_list " \
                  "must be configured"
            raise KeyError(msg)

        params = [item for item in params if isinstance(item, list)]
        if not params:
            msg = "Params dl_nr_subcell_list | ul_nr_subcell_list | dl_lte_subcell_list | ul_lte_subcell_list must be " \
                  "passed as lists"
            raise ValueError(msg)

        parameters = {"moduleDN": module_dn,
                      "dlNrSubcellList": dl_nr_subcell_list,
                      "ulNrSubcellList": ul_nr_subcell_list,
                      "dlLteCellList": dl_lte_subcell_list,
                      "ulLteCellList": ul_lte_subcell_list,
                      "captureOnEvent": capture_on_event}

        parameters = {k: v for k, v in parameters.items() if v is not None}

        response = self._api_client.execute_procedure(name="configureUPlaneL1IQData",
                                                      parameters=parameters,
                                                      timeout=timeout,
                                                      )
        if response is None:
            raise DataNotAvailable("Configure UPlaneL1IQData status has not been provided by M-Plane.")
        return response
